int get_pppox_l2tp_options(struct socket *sock, int level, int optname,
                           char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    struct pppox_sock *po = pppox_sk(sk);
    struct l2tp_tunnel *tunnel;
    struct l2tp_session *session;
    int len, err = 0;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!po->l2tp_session)
        return -ENOTCONN;

    session = po->l2tp_session;
    tunnel = session->tunnel;

    switch (optname) {
    case PPPOX_OPT_TTL:
        if (len < sizeof(u8))
            return -EINVAL;
        if (put_user(tunnel->session->session_id, (u8 __user *)optval))
            return -EFAULT;
        len = sizeof(u8);
        break;
    case PPPOX_OPT_TOS:
        if (len < sizeof(u8))
            return -EINVAL;
        if (put_user(tunnel->session->session_id >> 8, (u8 __user *)optval))
            return -EFAULT;
        len = sizeof(u8);
        break;
    default:
        return -EINVAL;
    }

    if (put_user(len, optlen))
        return -EFAULT;

    return 0;
}

int get_pppol2tp_sockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int len, ret = 0;
    void *data = NULL;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (!sock->sk->sk_state)
        return -ENOTCONN;

    session = pppol2tp_get_session(sk);
    if (!session)
        return -ENOENT;

    if (session->session_id == 0) {
        /* Tunnel options */
        if (optname == PPPOL2TP_SO_IFNAME) {
            len = strlen(session->ifname);
            if (len > *optlen)
                len = *optlen;
            if (copy_to_user(optval, session->ifname, len))
                ret = -EFAULT;
            put_user(len, optlen);
        } else {
            ret = -ENOPROTOOPT;
        }
    } else {
        /* Session options */
        ret = -ENOPROTOOPT;
    }

    return ret;
}

int get_pppol2tp_sockopts(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen) {
    int ret = -EFAULT;
    struct pppol2tp_session *session;
    struct pppol2tp_tunnel *tunnel;
    int len;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!sock->sk || !sock->sk->sk_state || !sock->sk->sk_state != TCP_ESTABLISHED)
        return -ENOTCONN;

    session = (struct pppol2tp_session *)sock->sk->sk_user_data;
    if (!session)
        return -EINVAL;

    tunnel = session->tunnel;

    switch (optname) {
        case PPPOLOPT_SESSION_ID:
            if (len < sizeof(session->session_id))
                return -EINVAL;
            if (copy_to_user(optval, &session->session_id, sizeof(session->session_id)))
                return -EFAULT;
            break;
        case PPPOLOPT_TUNNEL_ID:
            if (len < sizeof(tunnel->tid))
                return -EINVAL;
            if (copy_to_user(optval, &tunnel->tid, sizeof(tunnel->tid)))
                return -EFAULT;
            break;
        default:
            return -EINVAL;
    }

    put_user(sizeof(session->session_id), optlen);
    return 0;
}

int pppol2tp_getsockopt(struct socket *sock, int level, int optname, char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    struct pppol2tp_session *session;
    int len;
    int val;
    int ret = 0;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!sk || !sk->sk_prot || !sk->sk_prot->getsockopt)
        return -EINVAL;

    if (!sock->sk->sk_bound_dev_if || !sock->sk->sk_type)
        return -ENOTCONN;

    session = (struct pppol2tp_session *) sock->sk->sk_user_data;
    if (!session)
        return -EINVAL;

    if (session->session_id == 0) {
        /* Tunnel options */
        val = session->tunnel_options;
    } else {
        /* Session options */
        val = session->session_options;
    }

    len = min(len, sizeof(val));
    if (put_user(len, optlen))
        return -EFAULT;

    if (copy_to_user(optval, &val, len))
        return -EFAULT;

    return ret;
}

int get_pppol2tpsockopt(struct socket *sock, int level, int optname,
                        char __user *optval, int __user *optlen)
{
    struct sock *sk = sock->sk;
    int len, val;
    int err = 0;

    if (level != SOL_PPPOL2TP)
        return -EINVAL;

    if (get_user(len, optlen))
        return -EFAULT;

    if (len < 0)
        return -EINVAL;

    if (!sk->sk_state || !sk->sk_state == PPPOX_CONNECTED)
        return -ENOTCONN;

    if (optname == PPCP_PEER_FD) {
        val = (int)(unsigned long)pppol2tp_session_get(sk)->session_id;
        if (val == 0)
            return -EINVAL;

        if (put_user(val, (int __user *)optval))
            return -EFAULT;
        if (put_user(sizeof(val), optlen))
            return -EFAULT;
    } else {
        return -ENOPROTOOPT;
    }

    return err;
}
